package com.medtrack.batch.service;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
import com.medtrack.batch.dto.BatchRequest; import com.medtrack.batch.repository.BatchRepository; import com.medtrack.medicine.entity.Medicine; import com.medtrack.medicine.repository.MedicineRepository; import com.medtrack.shared.exception.DomainException; import com.medtrack.supplier.repository.SupplierRepository; import java.time.LocalDate; import java.util.*; import org.junit.jupiter.api.Test;
class BatchServiceTest { @Test void ac01_rejectsBatchInsideConfiguredShelfLifeWindow(){BatchRepository batches=mock(BatchRepository.class);MedicineRepository medicines=mock(MedicineRepository.class);SupplierRepository suppliers=mock(SupplierRepository.class);Medicine medicine=new Medicine("MED-ANT-00042","Amoxicillin",null,null,"TABLET","500mg","BOX",null,0,90,null);UUID id=UUID.randomUUID();when(medicines.findById(id)).thenReturn(Optional.of(medicine));BatchService service=new BatchService(batches,medicines,suppliers);DomainException e=assertThrows(DomainException.class,()->service.create(new BatchRequest("BAT-1",id,UUID.randomUUID(),LocalDate.now().minusMonths(1),LocalDate.now().plusDays(45),100,null)));assertEquals("BATCH_EXPIRY_TOO_SOON",e.getCode());verifyNoInteractions(suppliers);}}
